"""Item data for mods/armory. Read by build_armory.py.

Tiers: regular (30) · amazing (30) · superrare (20) · legendary (10), plus Wyrm upgrade and the arrow ladder.
Effects use the DSL in dsa.py:  ('p', pct, [...]) chance · ('if', status, [...]) vs target status · ('race', race, [...])
  actions: ('st', id) · ('dmg', fixed, dice_n, type, fx) · ('heal', n) · ('asp', n) · ('buff', se) · ('vfx', effect)
Placement: ('chest'|'npc', Id, level) explicit storage · ('loot', table, mode) loot table (mode 'all' = every entry drops).
Mechanics tagged [B] in comments depend on the Phase 0b retest (custom status effects, weapon Pe+hit, IsRace).
"""
D = lambda d: int(d * 100)   # ducats -> heller

# ---------------- custom status effects ----------------
HURT = lambda f, d, n, t: f'Hurt fixedDamage="{f}" dice="{d}" diceAmount="{n}" showNoDamage="false" damageType="{t}" actionSelection="script,quest,dialog"; '
WAIT = lambda s: f'WaitAction duration="{s}" permanent="false" actionSelection="script"; '
HEAL = lambda n: f'Heal fixedLE="{n}" dice="6" diceAmount="0" actionSelection="script,quest,dialog"; '
ASP = lambda n: f'RestoreAsP fixedAsP="{n}" dice="6" diceAmount="0" actionSelection="script"; '
