def W(key, tier, base, name, flavor, place, hit=(), mods='', imm='', aura=None, tint=None, value=None, stack=1, **stats):
    return dict(type='Weapon', key=key, tier=tier, base=base, name=name, flavor=flavor, place=place, hit=list(hit), mods=mods, imm=imm, aura=aura, tint=tint, value=value, stack=stack, stats=stats)
def A(key, tier, base, name, flavor, place, mods='', imm='', aura=None, tint=None, value=None, **stats):
    return dict(type='Armor', key=key, tier=tier, base=base, name=name, flavor=flavor, place=place, hit=[], mods=mods, imm=imm, aura=aura, tint=tint, value=value, stack=1, stats=stats)
def J(key, tier, base, name, flavor, place, mods='', imm='', aura=None, tint=None, value=None):
    return dict(type='Jewelry', key=key, tier=tier, base=base, name=name, flavor=flavor, place=place, hit=[], mods=mods, imm=imm, aura=aura, tint=tint, value=value, stack=1, stats={})
def S(key, tier, base, name, flavor, place, mods='', imm='', aura=None, tint=None, value=None, **stats):
    return dict(type='Shield', key=key, tier=tier, base=base, name=name, flavor=flavor, place=place, hit=[], mods=mods, imm=imm, aura=aura, tint=tint, value=value, stack=1, stats=stats)

